from typing import TYPE_CHECKING, List, Dict, Any, Optional
from abc import ABC, abstractmethod
import datetime
from taf.ul.sbts.energy_saving.decorators.connection import with_connection

if TYPE_CHECKING:
    from taf.ul.sbts.energy_saving.core.context import EnergySavingContext


class PowerGroup(ABC):
    """Base class for Power Saving Groups (NRPGRP, PSGRP)"""

    def __init__(self, context: 'EnergySavingContext'):
        self.context = context

    @property
    @abstractmethod
    def group_type(self) -> str:
        """Type of power group (NRPGRP, PSGRP)"""
        pass

    @property
    @abstractmethod
    def bts_type(self) -> str:
        """BTS type (NRBTS, LNBTS)"""
        pass

    @property
    @abstractmethod
    def cell_id_param(self) -> str:
        """Parameter name for cell ID in lbpsCellList (nrCellId, lnCelId)"""
        pass

    @property
    @abstractmethod
    def cell_type(self) -> str:
        """Cell type for this power group (NRCELL, LNCEL)"""
        pass

    @abstractmethod
    def get_recommended_parameters(self) -> Dict[str, Dict[str, Any]]:
        """Get recommended parameters"""
        pass

    def build_group_dist_name(self, mrbts_id: int, bts_id: int, group_id: int = 0) -> str:
        """Build power group distName"""
        return f"MRBTS-{mrbts_id}/{self.bts_type}-{bts_id}/{self.group_type}-{group_id}"

    def build_group_dist_name_from_subbts_dn(self, nrbts_dn: str, group_id: int = 0) -> str:
        """Build power group distName from subbts (NRBTS/LNBTS) distName"""
        if not nrbts_dn.endswith("/"):
            nrbts_dn += "/"

        return f"{nrbts_dn}{self.group_type}-{group_id}"

    def build_power_group_pattern(self, mrbts_id: Optional[int] = None, bts_id: Optional[int] = None) -> str:
        """Build regex pattern for finding power groups"""
        if mrbts_id is not None and bts_id is not None:
            return rf"MRBTS-{mrbts_id}/{self.bts_type}-{bts_id}/{self.group_type}-(\d+)$"
        elif mrbts_id is not None:
            return rf"MRBTS-{mrbts_id}/{self.bts_type}-\d+/{self.group_type}-(\d+)$"
        else:
            return rf"MRBTS-\d+/{self.bts_type}-\d+/{self.group_type}-(\d+)$"

    def get_default_lbps_cell(
            self, cell_id: int, cell_order: int = 100, use_ext_config: bool = False
    ) -> Dict[str, Any]:
        """Get default LBPS cell configuration"""
        return {
            self.cell_id_param: cell_id,
            "lbpsCellSOOrder": cell_order,
            "lbpsUseExtConfig": use_ext_config
        }

    def get_lbps_period_list(
            self, time_offset_minutes: int = 0, lbps_duration: int = 360, suspended: bool = False
    ) -> Dict[str, Any]:
        current_time = datetime.datetime.now() + datetime.timedelta(minutes=time_offset_minutes)
        current_day = current_time.strftime("%a")
        current_hour = current_time.strftime("%H")
        current_minute = current_time.strftime("%M")

        lbps_period_list = {
            "lbpsDayOfWeek": current_day,
            "lbpsStartTimeHour": int(current_hour),
            "lbpsStartTimeMinute": int(current_minute),
            "lbpsDuration": lbps_duration,
            "lbpsSuspended": "notSuspended" if suspended is False else "Suspended"
        }
        return lbps_period_list

    def add_lbps_period_list_to_delta(
            self,
            group_dn: str,
            time_offset_minutes: int = 0,
            lbps_duration: int = 360,
            suspended: bool = False,
            delta_id: int = 0,
    ) -> None:
        """Add LBPS period list to delta"""
        lbps_period_list = self.get_lbps_period_list(time_offset_minutes, lbps_duration, suspended)
        self.context.delta_manager.append_complex_item_to_delta(
            group_dn, list_name="lbpsPeriodList", delta_id=delta_id, **lbps_period_list)

    def get_lbps_cell_period_list(
        self, time_offset_minutes: int = 0, lbps_duration: int = 360, suspended: bool = False
    ) -> Dict[str, Any]:
        current_time = datetime.datetime.now() + datetime.timedelta(minutes=time_offset_minutes)
        current_day = current_time.strftime("%a")
        current_hour = current_time.strftime("%H")
        current_minute = current_time.strftime("%M")

        lbps_period_list = {
            "lbpsCellDayOfWeek": current_day,
            "lbpsCellStartTimeHour": int(current_hour),
            "lbpsCellStartTimeMinute": int(current_minute),
            "lbpsCellDuration": lbps_duration,
        }
        return lbps_period_list

    def add_default_power_group_object_to_delta(
            self, nrbts_dn: str, cell_id: int, group_id: int = 0, delta_id: int = 0
    ) -> str:
        """
        Add default power group object with predefined parameters to delta
        Direct port from create_default_nrpgrp_object/create_default_psgrp_object
        """
        group_dn = self.build_group_dist_name_from_subbts_dn(nrbts_dn, group_id)

        # Create managed object
        self.context.delta_manager.append_managed_object_to_delta(
            group_dn, "create", delta_id)

        # Add default period (from subclass implementation)
        default_period = self.get_lbps_period_list(lbps_duration=1)
        self.context.delta_manager.append_complex_item_to_delta(
            group_dn, list_name="lbpsPeriodList", delta_id=delta_id,
            **default_period)

        # Add default cell
        default_cell = self.get_default_lbps_cell(cell_id)
        self.context.delta_manager.append_complex_item_to_delta(group_dn, list_name="lbpsCellList", delta_id=delta_id,
                                                                **default_cell)
        return group_dn

    @with_connection
    def create_default_power_group_object(
            self, nrbts_dn: str, cell_id: int, group_id: int = 0, delta_id: int = 0, connection=None
    ) -> str:
        """
        Create default power group object with predefined parameters
        Direct port from create_default_nrpgrp_object/create_default_psgrp_object
        """
        with self.context.delta_manager.delta_context(
                delta_id, auto_commit=True, connection_alias=connection
        ) as delta:
            group_dn = self.add_default_power_group_object_to_delta(nrbts_dn, cell_id, group_id, delta)

        return group_dn

    def add_recommended_power_group_object_to_delta(
            self, nrbts_dn: str, cells_id: List[int], group_id: int = 0, delta_id: int = 0
    ) -> str:
        group_dn = self.build_group_dist_name_from_subbts_dn(nrbts_dn, group_id)

        self.context.delta_manager.append_managed_object_to_delta(group_dn, "create", delta_id)

        default_period = self.get_lbps_period_list(
            lbps_duration=1, time_offset_minutes=-1, suspended=False
        )
        self.context.delta_manager.append_complex_item_to_delta(
            group_dn, list_name="lbpsPeriodList", delta_id=delta_id, **default_period
        )

        for cell_order, cell_id in enumerate(cells_id, start=1):
            default_cell = self.get_default_lbps_cell(cell_id, cell_order=cell_order)
            self.context.delta_manager.append_complex_item_to_delta(
                group_dn, list_name="lbpsCellList", delta_id=delta_id, **default_cell
            )

        reccomended_params = self.get_recommended_parameters()
        for param_name, param_value in reccomended_params.items():
            self.context.delta_manager.append_parameter_update_to_delta(
                group_dn, parameter=param_name, value=param_value, delta_id=delta_id
            )
        return group_dn

    def get_cell_ids_from_lbpsCellList(self, xml_scf, group_dn: str) -> List[int]:
        """Get cell IDs from lbpsCellList of a power group"""
        cell_ids = []
        group_params = self.context.scf_manager.get_params_from_managed_object(xml_scf, group_dn)
        lbps_cell_list = group_params.get("lbpsCellList", [])
        lbps_cell_list = [lbps_cell_list] if isinstance(lbps_cell_list, dict) else lbps_cell_list
        for cell_list in lbps_cell_list:
            cell_ids.append(int(cell_list[self.cell_id_param]))
        return cell_ids

    def get_cell_ids_with_cells_order_from_lbpsCellList(self, xml_scf, group_dn: str) -> Dict[int, int]:
        """Get cell IDs with their lbpsCellSOOrder from lbpsCellList of a power group"""
        cell_ids_with_order = {}
        group_params = self.context.scf_manager.get_params_from_managed_object(xml_scf, group_dn)
        lbps_cell_list = group_params.get("lbpsCellList", [])
        lbps_cell_list = [lbps_cell_list] if isinstance(lbps_cell_list, dict) else lbps_cell_list
        for cell_list in lbps_cell_list:
            cell_id = int(cell_list[self.cell_id_param])
            cell_order = int(cell_list.get("lbpsCellSOOrder", 0))
            cell_ids_with_order[cell_id] = cell_order
        return cell_ids_with_order

    def get_lbpsLastCellSOEnabled_param(self, xml_scf, group_dn: str) -> bool:
        """Get lbpsLastCellSOEnabled parameter value from a power group"""
        group_params = self.context.scf_manager.get_params_from_managed_object(xml_scf, group_dn)
        last_cell_so_enabled = group_params.get("lbpsLastCellSOEnabled", "false")
        return last_cell_so_enabled

    @with_connection
    def disable_energy_saving_mode(self, power_group_dns, connection=None):
        """Disable energy saving for all groups in the given SCF XML"""
        with self.context.delta_manager.delta_context(auto_commit=True, connection_alias=connection) as delta_id:
            for group_dn in power_group_dns:
                self.add_lbps_period_list_to_delta(group_dn, lbps_duration=1, delta_id=delta_id)

    @with_connection
    def enable_energy_saving_mode(self, power_group_dns, xml_scf=None, connection=None):
        """Enable energy saving for all groups in the given SCF XML"""
        with self.context.delta_manager.delta_context(auto_commit=True, connection_alias=connection) as delta_id:
            for group_dn in power_group_dns:
                self.add_lbps_period_list_to_delta(group_dn, lbps_duration=1440, delta_id=delta_id)
            if xml_scf is None:
                string_scf = self.context.scf_manager.get_string_scf(connection=connection)
                xml_scf = self.context.scf_manager.string_to_xml_scf(string_scf)
            for group_dn in power_group_dns:
                power_group_params = self.context.scf_manager.get_params_from_managed_object(xml_scf, group_dn)
                if power_group_params.get("lbpsCellPeriodList") is not None:
                    for cell_period in power_group_params["lbpsCellPeriodList"]:
                        lbps_duration = self.get_lbps_cell_period_list(lbps_duration=1400)
                        cell_period.update(lbps_duration)
                        self.context.delta_manager.append_complex_item_to_delta(
                            group_dn,
                            list_name="lbpsCellPeriodList",
                            delta_id=delta_id,
                            **cell_period
                        )

    def get_existing_power_group_dist_names_from_scf(self, xml_scf) -> List[str]:
        """
        Get existing power group distNames from SCF

        Args:
            xml_scf: SCF XML object

        Returns:
            List of power group distNames
        """
        pattern = self.build_power_group_pattern()
        return self.context.scf_manager.get_distnames_by_pattern(xml_scf, pattern)

    def __repr__(self):
        return f"{self.__class__.__name__}(context={self.context.connection_alias})"
